import React from 'react';
import { ArrowLeft, ChevronDown, Globe2, Share2, ShieldCheck, Store } from 'lucide-react';
import { Link } from 'react-router-dom';
import { LocaleCurrencyPicker } from './LocaleCurrencyPicker';

type PublicStoreHeaderProps = {
  sellerAvatar?: string | null;
  sellerName: string;
  sellerPath?: string | null;
  onBack: () => void;
  onShare: () => void;
};

type PublicStoreFooterProps = {
  sellerName: string;
  sellerPath?: string | null;
};

const focusRing = 'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-300 focus-visible:ring-offset-2 focus-visible:ring-offset-[#09090b]';

const StoreIdentity = ({
  sellerAvatar,
  sellerName,
  sellerPath,
}: Pick<PublicStoreHeaderProps, 'sellerAvatar' | 'sellerName' | 'sellerPath'>) => {
  const identity = (
    <>
      {sellerAvatar ? (
        <img
          src={sellerAvatar}
          alt=""
          className="h-9 w-9 shrink-0 rounded-xl border border-white/10 object-cover"
          loading="eager"
          referrerPolicy="no-referrer"
        />
      ) : (
        <span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl border border-white/10 bg-white/[0.06] text-xs font-bold text-white">
          {sellerName.slice(0, 1).toUpperCase()}
        </span>
      )}
      <span className="min-w-0">
        <span className="block truncate text-sm font-semibold text-white">{sellerName}</span>
        <span className="public-store-desktop-copy text-[11px] text-white/36">Storefront on Wersee</span>
      </span>
    </>
  );

  return sellerPath ? (
    <Link
      to={sellerPath}
      className={`flex min-w-0 items-center gap-2.5 rounded-xl px-1.5 py-1 transition hover:bg-white/[0.05] ${focusRing}`}
      aria-label={`Visit ${sellerName} storefront`}
    >
      {identity}
    </Link>
  ) : (
    <div className="flex min-w-0 items-center gap-2.5 px-1.5 py-1">{identity}</div>
  );
};

export const PublicStoreHeader = ({
  sellerAvatar,
  sellerName,
  sellerPath,
  onBack,
  onShare,
}: PublicStoreHeaderProps) => (
  <header className="sticky top-0 z-[70] border-b border-white/[0.075] bg-[#09090b]/88 pt-[env(safe-area-inset-top,0px)] shadow-[0_12px_45px_rgba(0,0,0,.22)] backdrop-blur-2xl">
    <div className="mx-auto flex h-16 w-full max-w-[1240px] items-center gap-2 px-3 sm:gap-3 sm:px-6 lg:px-8">
      <button
        type="button"
        onClick={onBack}
        aria-label="Go back"
        className={`inline-flex min-h-11 shrink-0 items-center gap-2 rounded-xl px-2.5 text-sm font-medium text-white/58 transition hover:bg-white/[0.05] hover:text-white ${focusRing}`}
      >
        <ArrowLeft className="h-4 w-4" />
        <span className="hidden sm:inline">Back</span>
      </button>

      <span className="public-store-desktop-divider h-6 w-px bg-white/10" aria-hidden="true" />
      <Link
        to="/"
        aria-label="Wersee marketplace home"
        className={`public-store-desktop-brand shrink-0 items-center gap-2 rounded-xl px-1.5 py-1 ${focusRing}`}
      >
        <img src="/brand/wersee-icon-192.png" alt="" className="h-8 w-8 rounded-[10px] object-cover" />
        <span className="text-sm font-semibold tracking-[-0.025em] text-white/88">Wersee</span>
      </Link>

      <span className="public-store-desktop-divider h-6 w-px bg-white/10" aria-hidden="true" />
      <div className="min-w-0 flex-1">
        <StoreIdentity sellerAvatar={sellerAvatar} sellerName={sellerName} sellerPath={sellerPath} />
      </div>

      <Link
        to="/search"
        className={`public-store-desktop-brand min-h-11 items-center gap-2 rounded-xl px-3.5 text-xs font-semibold text-white/48 transition hover:bg-white/[0.05] hover:text-white ${focusRing}`}
      >
        <Store className="h-4 w-4" /> Marketplace
      </Link>

      <LocaleCurrencyPicker dark className="hidden shrink-0 lg:flex" />

      <details className="group relative shrink-0 lg:hidden">
        <summary
          className={`grid h-11 w-11 cursor-pointer list-none place-items-center rounded-xl border border-white/10 bg-white/[0.035] text-white/64 transition hover:bg-white/[0.07] hover:text-white [&::-webkit-details-marker]:hidden ${focusRing}`}
          aria-label="Language and currency"
        >
          <Globe2 className="h-4 w-4" />
        </summary>
        <div className="absolute right-0 top-[calc(100%+0.65rem)] w-[min(19rem,calc(100vw-1.5rem))] rounded-2xl border border-white/10 bg-[#121216]/98 p-3 shadow-[0_24px_80px_rgba(0,0,0,.5)] backdrop-blur-2xl">
          <div className="mb-2 flex items-center justify-between px-1 text-[11px] font-semibold uppercase tracking-[0.15em] text-white/35">
            Store preferences <ChevronDown className="h-3.5 w-3.5 group-open:rotate-180" />
          </div>
          <LocaleCurrencyPicker dark className="flex-col items-stretch [&>div]:justify-between [&>select]:w-full" />
        </div>
      </details>

      <button
        type="button"
        onClick={onShare}
        aria-label="Share product"
        className={`inline-flex min-h-11 shrink-0 items-center gap-2 rounded-xl border border-white/10 bg-white/[0.035] px-3 text-sm font-semibold text-white/70 transition hover:bg-white/[0.08] hover:text-white sm:px-4 ${focusRing}`}
      >
        <Share2 className="h-4 w-4" />
        <span className="hidden sm:inline">Share</span>
      </button>
    </div>
  </header>
);

export const PublicStoreFooter = ({ sellerName, sellerPath }: PublicStoreFooterProps) => (
  <footer className="relative mt-20 border-t border-white/[0.07] bg-[#070708] px-4 py-8 text-white sm:mt-28 sm:px-6 sm:py-10">
    <div className="mx-auto grid w-full max-w-[1180px] gap-8 sm:grid-cols-[minmax(0,1fr)_auto] sm:items-end">
      <div>
        <Link to="/" className={`inline-flex items-center gap-2.5 rounded-xl ${focusRing}`} aria-label="Wersee marketplace home">
          <img src="/brand/wersee-icon-192.png" alt="" className="h-9 w-9 rounded-xl object-cover" loading="lazy" />
          <span className="text-base font-semibold tracking-[-0.03em]">Wersee</span>
        </Link>
        <p className="mt-4 max-w-md text-sm leading-6 text-white/38">
          {sellerPath ? <Link to={sellerPath} className="font-semibold text-white/62 hover:text-white">{sellerName}</Link> : sellerName}{' '}
          sells through Wersee. Product information and availability come from this storefront.
        </p>
        <p className="mt-3 flex items-center gap-2 text-xs text-white/30">
          <ShieldCheck className="h-4 w-4 text-emerald-300/80" /> Secure checkout with payment details handled by Stripe.
        </p>
      </div>

      <nav aria-label="Storefront footer" className="flex max-w-sm flex-wrap gap-x-5 gap-y-3 text-xs font-medium text-white/42 sm:justify-end">
        <Link to="/buyer-protection" className="hover:text-white">Buyer protection</Link>
        <Link to="/support" className="hover:text-white">Support</Link>
        <Link to="/terms" className="hover:text-white">Terms</Link>
        <Link to="/privacy-policy" className="hover:text-white">Privacy</Link>
      </nav>
    </div>
  </footer>
);
